import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
const runtimes = await Promise.all([import('/tmp/rank223-after/out/index.js'),import('/tmp/rank224-compiler/out/index.js')]);
let checks=0;
for(const limit of [...Array(31).keys(),50,99,100,101,199,200,201,300,1000]){
 let expected=0;
 for(let a=1;a<=limit/3;a++) for(let b=a;b<=(limit-a)/2;b++) {const c=Math.round(Math.sqrt(a*a+b*b+1));if(c>=b&&a+b+c<=limit&&c*c===a*a+b*b+1)expected++;}
 for(const variant of ['original','kernels','staged','fused'])for(const {Interpreter} of runtimes)for(const compilation of [true,false]){
  const r=new Interpreter(()=>{},{compilation});try{r.execute(readFileSync(`/tmp/rank224-${variant}.ra`,'utf8').replace('option Limit integer = 75000000',`option Limit integer = ${limit}`));assert.equal(String(r.variables.get('Answer')),String(expected),`${variant} ${limit} ${compilation}`);checks++;}finally{r.dispose()}
 }
}
console.log(JSON.stringify({checks}));

